pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }

    function testFuzz_property(address fuzz_baseToken, address fuzz_nft, uint128 virtualBaseTokenReserves, uint128 virtualNftReserves, uint56 changeFee, uint16 feeRate, bytes32 merkleRoot, bool useStolenNftOracle, bool payRoyalties) public {

        vm.assume(feeRate <= 60000);

        bool ok;
        try c.initialize(fuzz_baseToken, fuzz_nft, virtualBaseTokenReserves, virtualNftReserves, changeFee, feeRate, merkleRoot, useStolenNftOracle, payRoyalties) {
            ok = true;
        } catch {
            ok = false;
        }

        if (!ok) return;

        assertTrue(c.baseToken() == fuzz_baseToken);
    }
}
